import { useState, useEffect } from 'react';
import { fmt, getCurrentYM } from '../utils/format';
import { STORES } from '../utils/config';
import { useSheets } from '../hooks/useSheets';
import { buildCostMap, erpSalesDate } from '../utils/salesCalc';

// 2026-10-23 新增：把平台報表上的代號轉成商品總表標準代號（例如 momo 自己的商品編號
// 「8233476」轉成「BDLN101」），見 useSheets.js 的 readCodeMap() 說明。沒登記過的代號
// 原樣傳回（代表本來就是標準代號，或還沒登記對應關係）。
function mapCode(code, codeMap) {
  return (codeMap && Object.prototype.hasOwnProperty.call(codeMap, code)) ? codeMap[code] : code;
}

const PLATFORMS = [
  { id:'ALL',            label:'全部',      color:'var(--text)' },
  { id:'TOOLA_SHOPLINE', label:'TOOLA 官網', color:'#00c8ff' },
  { id:'MOMO',           label:'momo',      color:'#ff4488' },
  { id:'TOOLA_SHOPEE',   label:'TOOLA 蝦皮', color:'#00c8ff' },
  { id:'TAKUYA_SHOPEE',  label:'拓屋 蝦皮',  color:'#ffcc00' },
  { id:'TAKUYA_SHOPLINE',label:'拓屋 官網',  color:'#ffcc00' },
  { id:'ERP',            label:'經銷',      color:'#00e87a' },
];

export default function SalesPage() {
  const { readAllSales, readProducts, readCodeMap } = useSheets();
  const [platFilter, setPlatFilter] = useState('ALL');
  const [rows, setRows] = useState([]);
  const [costMap, setCostMap] = useState({});
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  // 月份切換（右上角）：viewMode='all' 顯示全部歷史資料，'month' 只顯示 ym 那個月份。
  // 經銷(ERP) 2026-10-22 起，上傳時可以手動指定銷貨月份了（見 utils/salesCalc.js 的
  // erpSalesDate 說明），有指定月份的經銷資料現在也能在「選擇月份」檢視下正確顯示；
  // 這次修正之前上傳的舊經銷資料沒有這個月份，仍然只會出現在「全部」檢視。
  const [viewMode, setViewMode] = useState('month');
  const [ym, setYm] = useState(() => getCurrentYM());

  // 抽成獨立函式，除了畫面第一次載入呼叫，也給「重新整理」按鈕用——
  // 之前只有 useEffect 在畫面第一次打開時抓一次資料，如果開單/上傳報表後
  // 沒有離開這頁再回來（沒有重新 mount），畫面上不會自動看到最新資料，
  // 使用者會誤以為「剛剛的資料不見了」，其實是還沒有重新讀取。
  const loadData = () => {
    return Promise.all([readAllSales(), readProducts(), readCodeMap()]).then(([sales, prods, codeMap]) => {
      // readProducts() 已經把套組/多入組的成本從套組成分表換算好了，這裡不用再另外處理
      setCostMap(buildCostMap(prods));
      // 合併所有平台資料——欄位索引對照 utils/salesCalc.js 的說明（跟 excelParser.js
      // 實際寫入 Sheets 的欄位順序一致）。之前這裡官網用「訂單狀態」欄位當代號、
      // momo 的營收沒有乘上數量、經銷把「客戶名稱」欄位當日期，算出來的代號/營收都是錯的，
      // 已經修正。官網/蝦皮同時也改成看每一列最後一欄的賣場標記，正確分出 TOOLA / 拓屋，
      // 不會再把拓屋的資料誤算成 TOOLA（也讓拓屋的營收不會一直顯示 0）。
      // ⚠ 2026-10-23 新增：code 一律先經過 mapCode() 轉換——momo（或其他平台）報表上
      // 有時候是平台自己的商品編號（例如「8233476」），不是商品總表的標準代號，轉換後
      // 下面「依產品代號彙整」才查得到 costMap 裡的成本，不會再顯示查無資料（見 mapCode 說明）。
      const shoplineTag = r => r[r.length-1] || 'TOOLA_SHOPLINE';
      const shopeeTag   = r => r[r.length-1] || 'TOOLA_SHOPEE';
      const allRows = [
        ...sales.shopline.map(r => ({ platform:shoplineTag(r), orderId:r[0], date:r[1], code:mapCode(String(r[4]||'').trim(), codeMap), name:r[3], qty:Number(r[5])||0, price:Number(r[6])||0, revenue:Number(r[7])||0 })),
        // momo 營收用「進價」(r[5])，不是「售價」(r[6])——售價是零售價，進價才是momo實際匯給你的錢
        // （2026-09-23 已跟 Willie 確認，詳見 utils/salesCalc.js 的 calcMomoTotals 說明）。
        ...sales.momo.map(r    => ({ platform:'MOMO',          orderId:r[0], date:r[1], code:mapCode(String(r[2]||'').trim(), codeMap), name:r[3], qty:Number(r[4])||0, price:Number(r[5])||0, revenue:(Number(r[5])||0)*(Number(r[4])||0) })),
        ...sales.shopee.map(r  => ({ platform:shopeeTag(r),    orderId:r[0], date:r[1], code:mapCode(String(r[2]||'').trim(), codeMap), name:r[3], qty:Number(r[4])||0, price:Number(r[5])||0, revenue:Number(r[6])||0 })),
        ...sales.erp.map(r     => ({ platform:'ERP',           orderId:r[0], date:erpSalesDate(r), code:mapCode(String(r[2]||'').trim(), codeMap), name:r[3], qty:Number(r[4])||0, price:Number(r[4]) ? Math.round((Number(r[7])||0)/Number(r[4])) : 0, revenue:Number(r[7])||0 })),
        // revenue 改用「含稅金額」(r[13])，不是「小計」(r[12])——手動開單有分未稅/含稅兩種輸入，
        // 「小計」在這兩種情況下基礎不一樣（未稅訂單=稅前金額，含稅訂單=稅後金額），直接加總會讓
        // 未稅訂單少算5%營收，跟其他平台「一律用實收含稅金額」的營收基礎對不起來（詳見 salesCalc.js
        // 的 calcOrdersTotals 說明）。「含稅金額」欄位不管哪種輸入方式，存的都已經是換算好的稅後總額。
        ...sales.orders.map(r  => ({ platform:r[2]||'手動開單', orderId:r[0], date:r[1], code:r[8], name:r[9], qty:Number(r[10])||0, price:Number(r[11])||0, revenue:Number(r[13])||0 })),
      ];
      setRows(allRows);
    });
  };

  useEffect(() => {
    loadData().catch(() => {}).finally(() => setLoading(false));
  }, []); // eslint-disable-line

  const handleRefresh = () => {
    setRefreshing(true);
    loadData().catch(() => {}).finally(() => setRefreshing(false));
  };

  const shiftMonth = (delta) => {
    setViewMode('month');
    setYm(p => {
      let m = p.month + delta, y = p.year;
      if (m < 1) { m = 12; y -= 1; }
      if (m > 12) { m = 1; y += 1; }
      return { year:y, month:m };
    });
  };

  // 「全部」檢視顯示所有歷史資料；選了特定月份時，只有「有日期」的資料才會顯示——
  // 經銷(ERP) 2026-10-22 起上傳時有指定月份的資料會有日期，可以正常被篩選；
  // 這次修正之前上傳的舊經銷資料沒有日期，仍然只會出現在「全部」檢視。
  const monthStr = `${ym.year}-${String(ym.month).padStart(2,'0')}`;
  const visibleRows = viewMode === 'all' ? rows : rows.filter(r => r.date && r.date.startsWith(monthStr));

  // 依產品代號彙整
  const summary = {};
  visibleRows.filter(r => platFilter === 'ALL' || r.platform === platFilter).forEach(r => {
    if (!r.code) return;
    if (!summary[r.code]) {
      // matched=false 代表這個代號在商品總表/套組成分表都查無資料（不是「成本剛好填0」），
      // 這種情況下面表格會用紅字提醒，成本 0 不代表真的免費，是漏建檔
      const matched = Object.prototype.hasOwnProperty.call(costMap, r.code);
      summary[r.code] = { code:r.code, name:r.name||'', cost:costMap[r.code]||0, matched, qty:0, revenue:0, byPlat:{} };
    }
    summary[r.code].qty     += r.qty;
    summary[r.code].revenue += r.revenue;
    summary[r.code].byPlat[r.platform] = (summary[r.code].byPlat[r.platform] || 0) + r.qty;
  });

  const summaryRows = Object.values(summary).sort((a,b) => b.revenue - a.revenue);
  const totalQty     = summaryRows.reduce((s,r) => s+r.qty, 0);
  const totalRevenue = summaryRows.reduce((s,r) => s+r.revenue, 0);
  const totalCost    = summaryRows.reduce((s,r) => s+r.qty*r.cost, 0);
  const unmatchedRows    = summaryRows.filter(r => !r.matched);
  const unmatchedRevenue = unmatchedRows.reduce((s,r) => s+r.revenue, 0);

  return (
    <div>
      <div style={{ display:'flex', gap:6, marginBottom:16, flexWrap:'wrap', alignItems:'center' }}>
        {PLATFORMS.map(p => (
          <button key={p.id}
            className={`btn btn-sm ${platFilter===p.id?'btn-primary':'btn-ghost'}`}
            style={platFilter===p.id ? { borderColor:p.color, color:p.color, background:`${p.color}15` } : {}}
            onClick={() => setPlatFilter(p.id)}>
            {p.label}
          </button>
        ))}
        <div style={{ display:'flex', alignItems:'center', gap:6, marginLeft:'auto' }}>
          <button className={`btn btn-sm ${viewMode==='all'?'btn-primary':'btn-ghost'}`}
            onClick={() => setViewMode('all')}>全部期間</button>
          <button className="btn btn-sm btn-ghost" onClick={() => shiftMonth(-1)}>‹</button>
          <span style={{ fontSize:14, color:'var(--text)', minWidth:78, textAlign:'center', fontFamily:'var(--mono)' }}>
            {viewMode==='all' ? '全部' : `${ym.year}年${ym.month}月`}
          </span>
          <button className="btn btn-sm btn-ghost" onClick={() => shiftMonth(1)}>›</button>
        </div>
        <button className="btn btn-sm btn-ghost"
          onClick={handleRefresh} disabled={refreshing}>
          {refreshing ? '↻ 重新整理中…' : '↻ 重新整理（抓最新資料）'}
        </button>
      </div>
      <div style={{ fontSize:12, color:'var(--muted)', marginTop:-10, marginBottom:16 }}>
        剛開單或剛上傳報表後，如果沒看到最新資料，先點右上「重新整理」，不用整頁重新整理網頁。
        {viewMode!=='all' && <> ◈ 經銷(ERP)報表如果是這次修正之前上傳、沒有指定月份的舊資料，只會出現在「全部期間」檢視。</>}
      </div>

      {!loading && unmatchedRows.length > 0 && (
        <div style={{ background:'rgba(255,196,0,0.08)', border:'1px solid rgba(255,196,0,0.35)', borderRadius:8, padding:'10px 14px', marginBottom:16, fontSize:13, color:'var(--yellow, #f5c400)' }}>
          ⚠ 下面有 {unmatchedRows.length} 個代號（紅字標示），在商品總表、套組成分表都查無資料，共 {fmt.currency(unmatchedRevenue)} 營收的成本沒有算到（顯示的成本 $0 不代表真的免費，是還沒建檔）。
          麻煩到 Google Sheets 的「商品總表」（如果是多入組/套組，還要到「套組成分表」）把這些代號補上，成本才會正確。
        </div>
      )}

      {loading
        ? <div style={{ textAlign:'center', padding:'60px', color:'var(--muted)' }}>載入中…</div>
        : <div className="card">
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th style={{ paddingRight:4 }}>代號</th><th style={{ paddingLeft:4 }}>品名</th>
                    <th style={{ textAlign:'right' }}>含稅成本</th>
                    <th style={{ textAlign:'right', color:'var(--purple)' }}>銷售數量</th>
                    <th style={{ textAlign:'right', color:'var(--cyan)' }}>銷售金額</th>
                    <th style={{ textAlign:'right', color:'var(--pink)' }}>銷貨成本</th>
                    <th style={{ textAlign:'right', color:'var(--green)' }}>毛利</th>
                    <th style={{ textAlign:'center' }}>資料狀態</th>
                  </tr>
                </thead>
                <tbody>
                  {summaryRows.length === 0
                    ? <tr><td colSpan={8} style={{ textAlign:'center', padding:'40px', color:'var(--muted)' }}>◻ 尚無資料，請先上傳報表</td></tr>
                    : summaryRows.map(r => {
                        const costTotal = r.qty * r.cost;
                        const gross = r.revenue - costTotal;
                        return (
                          <tr key={r.code} style={!r.matched ? { background:'rgba(255,80,80,0.06)' } : undefined}>
                            <td className="td-mono" style={{ color: r.matched ? 'var(--cyan)' : 'var(--red, #ff5050)', fontWeight:700, fontSize:13, paddingRight:4 }}>{r.code}</td>
                            <td style={{ maxWidth:280, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap', paddingLeft:4 }} title={r.name}>{r.name}</td>
                            <td className="td-right td-mono" style={{ color:'var(--muted)' }}>{fmt.currency(r.cost)}</td>
                            <td className="td-right td-mono" style={{ color:'var(--purple)', fontWeight:700 }}>{r.qty}</td>
                            <td className="td-right td-mono" style={{ color:'var(--cyan)', fontWeight:600 }}>{fmt.currency(r.revenue)}</td>
                            <td className="td-right td-mono" style={{ color:'var(--pink)' }}>{fmt.currency(costTotal)}</td>
                            <td className="td-right td-mono" style={{ color: gross>=0?'var(--green)':'var(--red)', fontWeight:600 }}>{fmt.currency(gross)}</td>
                            <td style={{ textAlign:'center', fontSize:12 }}>
                              {r.matched
                                ? <span style={{ color:'var(--muted)' }}>✓</span>
                                : <span style={{ color:'var(--red, #ff5050)', fontWeight:600 }}>⚠ 查無資料</span>}
                            </td>
                          </tr>
                        );
                      })
                  }
                </tbody>
                <tfoot>
                  <tr style={{ background:'rgba(0,245,255,0.06)', borderTop:'2px solid var(--cyan)' }}>
                    <td colSpan={3} style={{ fontFamily:'var(--title)', fontWeight:700, color:'var(--cyan)', padding:'11px 14px', letterSpacing:2 }}>合計</td>
                    <td className="td-right td-mono" style={{ fontWeight:700, color:'var(--purple)' }}>{totalQty}</td>
                    <td className="td-right td-mono" style={{ fontWeight:700, color:'var(--cyan)' }}>{fmt.currency(totalRevenue)}</td>
                    <td className="td-right td-mono" style={{ fontWeight:700, color:'var(--pink)' }}>{fmt.currency(totalCost)}</td>
                    <td className="td-right td-mono" style={{ fontWeight:700, color:'var(--green)' }}>{fmt.currency(totalRevenue-totalCost)}</td>
                    <td></td>
                  </tr>
                </tfoot>
              </table>
            </div>
          </div>
      }
    </div>
  );
}
